files.src/App.css:
:root {
  color-scheme: dark;
}

html,body {
  margin: 0;
  height: 100%;
  background: #020617;
}

body {
  font-family: system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;
}

.app {
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: #020617;
  color: #e5e7eb;
  padding: 24px;
}

.layout {
  width: 100%;
  max-width: 520px;
  display: grid;
  gap: 16px;
}

.column {
  background: #020617;
  border-radius: 16px;
  border: 1px solid #1f2937;
  padding: 16px 16px 12px;
  display: grid;
  gap: 12px;
}

.title {
  margin: 0;
  font-size: 18px;
  font-weight: 700;
}

.subtitle {
  margin: 4px 0 0;
  font-size: 13px;
  color: #9ca3af;
}

.product-list,.cart-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
}

.product-card {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 10px 10px;
  border-radius: 12px;
  border: 1px solid #1f2937;
  background: #020617;
}

.product-main {
  display: grid;
  gap: 2px;
}

.product-name {
  font-size: 14px;
  font-weight: 600;
}

.product-price {
  font-size: 13px;
  color: #a3e635;
}

.cart-header {
  display: grid;
  gap: 4px;
}

.cart-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 10px 10px;
  border-radius: 12px;
  border: 1px solid #1f2937;
  background: #020617;
}

.cart-info {
  display: grid;
  gap: 4px;
}

.cart-name {
  font-size: 14px;
  font-weight: 600;
}

.cart-meta {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  color: #9ca3af;
}

.unit-price,.line-total {
  font-variant-numeric: tabular-nums;
}

.times,.equals {
  opacity: .7;
}

.cart-actions {
  display: flex;
  gap: 6px;
}

button {
  border-radius: 999px;
  border: 1px solid #374151;
  background: #020617;
  color: #e5e7eb;
  padding: 6px 12px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}

button:hover {
  border-color: #a3e635;
}

button.ghost {
  background: transparent;
}

button.danger {
  border-color: #f97316;
  color: #f97316;
}

.empty {
  margin: 4px 0 0;
  font-size: 13px;
  color: #6b7280;
}
